        ["set.sub"] = ["Your own mouse file, safety, scheduled cleanup and the look of the app.", "Tu archivo de ratón, seguridad, limpieza programada y el aspecto del programa.", "Свой файл мыши, безопасность, плановая очистка и оформление программы.", "Eigene Maus-Datei, Sicherheit, geplante Bereinigung und das Aussehen der App.", "Votre fichier de souris, la sécurité, le nettoyage planifié et l'apparence de l'appli.", "鼠标文件、安全、计划清理和程序外观。"],
        ["set.files"] = ["CS2 FILES", "ARCHIVOS DE CS2", "ФАЙЛЫ CS2", "CS2-DATEIEN", "FICHIERS CS2", "CS2 文件"],
        ["set.look"] = ["APPEARANCE", "APARIENCIA", "ОФОРМЛЕНИЕ", "DARSTELLUNG", "APPARENCE", "外观"],
        ["set.reg.title"] = ["Mouse settings (.reg)", "Configuración del ratón (.reg)", "Настройки мыши (.reg)", "Mauseinstellungen (.reg)", "Réglages de la souris (.reg)", "鼠标设置 (.reg)"],
        ["set.reg.sub"] = ["By default the app applies Windows' default mouse settings (pointer speed, Enhance pointer precision and the stock curves). Load your own .reg to apply it instead.", "Por defecto se aplica la configuración de ratón predeterminada de Windows (velocidad, “Mejorar precisión del puntero” y las curvas de fábrica). Carga tu propio .reg para aplicarlo en su lugar.", "По умолчанию применяются стандартные настройки мыши Windows (скорость, «Повышенная точность указателя» и заводские кривые). Загрузите свой .reg, чтобы применить его.", "Standardmäßig werden die Windows-Standard-Mauseinstellungen angewendet (Zeigergeschwindigkeit, „Zeigerbeschleunigung verbessern“ und Werkskurven). Lade deine eigene .reg, um sie stattdessen anzuwenden.", "Par défaut, les réglages de souris par défaut de Windows sont appliqués (vitesse, « Améliorer la précision du pointeur » et courbes d'origine). Chargez votre propre .reg pour l'appliquer à la place.", "默认应用 Windows 默认鼠标设置（指针速度、“提高指针精确度”和出厂曲线）。加载你自己的 .reg 即可改为应用它。"],
        ["set.reg.default"] = ["Default: Windows' default mouse settings", "Por defecto: configuración de ratón predeterminada de Windows", "По умолчанию: стандартные настройки мыши Windows", "Standard: Windows-Standard-Mauseinstellungen", "Par défaut : réglages de souris par défaut de Windows", "默认：Windows 默认鼠标设置"],
        ["set.custom"] = ["Yours: {0}", "Tuyo: {0}", "Свой: {0}", "Eigene: {0}", "Le vôtre : {0}", "自定义：{0}"],
        ["set.choose"] = ["Choose file...", "Elegir archivo...", "Выбрать файл...", "Datei wählen...", "Choisir un fichier...", "选择文件..."],
        ["set.useDefault"] = ["Use default", "Usar el de por defecto", "По умолчанию", "Standard verwenden", "Par défaut", "使用默认"],
        ["set.reg.filter"] = ["Registry file", "Archivo de registro", "Файл реестра", "Registrierungsdatei", "Fichier de registre", "注册表文件"],
        ["toast.set.custom"] = ["Using your file: {0}", "Usando tu archivo: {0}", "Используется ваш файл: {0}", "Deine Datei wird verwendet: {0}", "Votre fichier est utilisé : {0}", "正在使用你的文件：{0}"],
        ["toast.set.default"] = ["Back to the default file", "Vuelve a usarse el archivo por defecto", "Снова используется файл по умолчанию", "Wieder die Standarddatei", "Retour au fichier par défaut", "已恢复为默认文件"],
        ["lg.custom.missing"] = ["Your file no longer exists, using the default one: {0}", "Tu archivo ya no existe, se usa el de por defecto: {0}", "Ваш файл не найден, используется файл по умолчанию: {0}", "Deine Datei existiert nicht mehr, Standard wird genutzt: {0}", "Votre fichier n'existe plus, celui par défaut est utilisé : {0}", "你的文件已不存在，改用默认文件：{0}"],
        ["lg.mouse.custom"] = ["Mouse: using your file {0}", "Ratón: usando tu archivo {0}", "Мышь: используется ваш файл {0}", "Maus: deine Datei {0} wird genutzt", "Souris : utilisation de votre fichier {0}", "鼠标：使用你的文件 {0}"],

        // ---------- Plan de energia ----------
        ["mod.power"] = ["RNX Performance power plan", "Plan de energía RNX Performance", "План электропитания RNX Performance", "Energiesparplan RNX Performance", "Mode de gestion de l'alimentation RNX Performance", "RNX Performance 电源计划"],
        ["cs2.pw.sub"] = ["Imports and activates the RNX Performance power plan, tuned for maximum performance and minimum latency in games. It's always imported with the same ID, so it never duplicates. Everything applies it automatically.", "Importa y activa el plan de energía RNX Performance, ajustado para máximo rendimiento y mínima latencia en juegos. Siempre se importa con el mismo identificador, así que nunca se duplica. El modo Todo lo aplica automáticamente.", "Импортирует и включает план электропитания RNX Performance, настроенный на максимальную производительность и минимальную задержку в играх. Он всегда импортируется с одним и тем же ID, поэтому не дублируется. Режим «Всё» применяет его автоматически.", "Importiert und aktiviert den Energiesparplan RNX Performance, abgestimmt auf maximale Leistung und minimale Latenz in Spielen. Er wird immer mit derselben ID importiert und daher nie doppelt angelegt. „Alles“ wendet ihn automatisch an.", "Importe et active le mode d'alimentation RNX Performance, réglé pour des performances maximales et une latence minimale en jeu. Il est toujours importé avec le même identifiant, il n'est donc jamais dupliqué. « Tout » l'applique automatiquement.", "导入并启用 RNX Performance 电源计划，为游戏中的最高性能和最低延迟而调校。每次都使用相同的 ID 导入，因此不会重复。“全部”模式会自动应用它。"],
        ["cs2.pw.btn"] = ["Activate plan", "Activar plan", "Включить план", "Plan aktivieren", "Activer le mode", "启用计划"],
        ["step.power"] = ["RNX Performance power plan", "Plan de energía RNX Performance", "План электропитания RNX Performance", "Energiesparplan RNX Performance", "Mode d'alimentation RNX Performance", "RNX Performance 电源计划"],
        ["plan.power"] = ["Power plan", "Plan de energía", "План электропитания", "Energiesparplan", "Mode d'alimentation", "电源计划"],
        ["lg.pw.missing"] = ["POWER: RNX_Performance.pow is missing from the program", "ENERGÍA: falta RNX_Performance.pow dentro del programa", "ПИТАНИЕ: в программе нет RNX_Performance.pow", "ENERGIE: RNX_Performance.pow fehlt im Programm", "ÉNERGIE : RNX_Performance.pow est absent du programme", "电源：程序中缺少 RNX_Performance.pow"],
        ["lg.pw.reimport"] = ["POWER: the bundled plan changed, re-importing it", "ENERGÍA: el plan incluido ha cambiado, se reimporta", "ПИТАНИЕ: встроенный план изменился, повторный импорт", "ENERGIE: der enthaltene Plan hat sich geändert, wird neu importiert", "ÉNERGIE : le mode inclus a changé, réimportation", "电源：内置计划已更改，正在重新导入"],
        ["lg.pw.imported"] = ["POWER: RNX Performance plan imported", "ENERGÍA: plan RNX Performance importado", "ПИТАНИЕ: план RNX Performance импортирован", "ENERGIE: Plan RNX Performance importiert", "ÉNERGIE : mode RNX Performance importé", "电源：已导入 RNX Performance 计划"],
        ["lg.pw.importFail"] = ["POWER: importing the plan failed: {0}", "ENERGÍA: no se pudo importar el plan: {0}", "ПИТАНИЕ: не удалось импортировать план: {0}", "ENERGIE: Import des Plans fehlgeschlagen: {0}", "ÉNERGIE : échec de l'import du mode : {0}", "电源：导入计划失败：{0}"],
