        ["step.rp"] = ["Restore point", "Punto de restauración", "Точка восстановления", "Wiederherstellungspunkt", "Point de restauration", "还原点"],
        ["set.safety"] = ["Safety", "Seguridad", "Безопасность", "Sicherheit", "Sécurité", "安全"],
        ["set.rp.title"] = ["Restore point before Full and Everything", "Punto de restauración antes de Completa y Todo", "Точка восстановления перед «Полной» и «Всё»", "Wiederherstellungspunkt vor Vollständig und Alles", "Point de restauration avant Complet et Tout", "在完整和全部模式前创建还原点"],
        ["set.rp.sub"] = ["Creates a Windows restore point first, so registry, NVIDIA profile and power plan changes can be rolled back from Windows. Windows allows one every 24 hours; if there's a recent one, that one is kept.", "Crea antes un punto de restauración de Windows para poder deshacer desde Windows los cambios en el registro, el perfil NVIDIA y el plan de energía. Windows permite uno cada 24 horas; si ya hay uno reciente, se usa ese.", "Сначала создаёт точку восстановления Windows, чтобы изменения реестра, профиля NVIDIA и плана электропитания можно было откатить средствами Windows. Windows позволяет одну точку в 24 часа; если есть свежая, используется она.", "Erstellt zuerst einen Windows-Wiederherstellungspunkt, damit Änderungen an Registry, NVIDIA-Profil und Energiesparplan über Windows rückgängig gemacht werden können. Windows erlaubt einen pro 24 Stunden; gibt es schon einen aktuellen, wird dieser behalten.", "Crée d'abord un point de restauration Windows pour pouvoir annuler depuis Windows les modifications du registre, du profil NVIDIA et du mode d'alimentation. Windows en autorise un toutes les 24 heures ; s'il y en a un récent, il est conservé.", "先创建一个 Windows 还原点，以便通过 Windows 撤销对注册表、NVIDIA 配置文件和电源计划的更改。Windows 每 24 小时只允许创建一个；如果已有最近的还原点，则沿用它。"],
        ["lg.rp.ok"] = ["RESTORE: restore point created", "RESTAURACIÓN: punto de restauración creado", "ВОССТАНОВЛЕНИЕ: точка восстановления создана", "WIEDERHERSTELLUNG: Wiederherstellungspunkt erstellt", "RESTAURATION : point de restauration créé", "还原：已创建还原点"],
        ["lg.rp.recent"] = ["RESTORE: Windows already has a restore point from {0} (it allows one every 24 h), that one is kept", "RESTAURACIÓN: Windows ya tiene un punto de restauración del {0} (permite uno cada 24 h), se usa ese", "ВОССТАНОВЛЕНИЕ: в Windows уже есть точка от {0} (одна в 24 ч), используется она", "WIEDERHERSTELLUNG: Windows hat bereits einen Punkt vom {0} (einer pro 24 h), dieser wird behalten", "RESTAURATION : Windows a déjà un point du {0} (un toutes les 24 h), il est conservé", "还原：Windows 已有 {0} 的还原点（每 24 小时一个），将沿用它"],
        ["lg.rp.disabled"] = ["RESTORE: no restore point created (code {0}). System Protection is probably off for C: (System > System protection)", "RESTAURACIÓN: no se creó el punto de restauración (código {0}). Seguramente la Protección del sistema está desactivada en C: (Sistema > Protección del sistema)", "ВОССТАНОВЛЕНИЕ: точка не создана (код {0}). Вероятно, защита системы для C: отключена (Система > Защита системы)", "WIEDERHERSTELLUNG: kein Punkt erstellt (Code {0}). Der Computerschutz für C: ist vermutlich aus (System > Computerschutz)", "RESTAURATION : aucun point créé (code {0}). La protection du système est sans doute désactivée sur C: (Système > Protection du système)", "还原：未创建还原点（代码 {0}）。C: 的系统保护可能已关闭（系统 > 系统保护）"],
